 async function loadTeam(){if(!supabase||!user)return;setLoading(true);const {data:orgId,error:orgError}=await supabase.rpc("current_user_organization_id");if(orgError||!orgId){setTeamError(orgError?.message||"Não foi possível identificar a organização. Confirme a migration 002.");setTeamMembers([]);setTeamOrgId("");setLoading(false);return}setTeamOrgId(String(orgId));const {data,error}=await supabase.from("organization_members").select("id,organization_id,user_id,role,invited_by,created_at").eq("organization_id",orgId).order("created_at",{ascending:true});if(error){setTeamError(error.message);setTeamMembers([])}else{setTeamError("");setTeamMembers((data||[]) as TeamMember[])}setLoading(false)}
