 const salesPerformance=useMemo(()=>{const map=new Map<string,{seller:string;opportunities:number;won:number;wonValue:number;proposals:number;accepted:number;contracts:number;monthlyRevenue:number}>();const get=(name:any)=>{const seller=String(name||"").trim()||"Sem responsável";if(!map.has(seller))map.set(seller,{seller,opportunities:0,won:0,wonValue:0,proposals:0,accepted:0,contracts:0,monthlyRevenue:0});return map.get(seller)!};for(const r of rows){const p=r.payload||{};if(r.module==="opportunities"){const x=get(p.owner);x.opportunities++;if(p.stage==="Ganha"){x.won++;x.wonValue+=Number(p.value||0)}}else if(r.module==="proposals"){const x=get(p.owner);x.proposals++;if(p.status==="Aceita")x.accepted++}else if(r.module==="contracts"){const x=get(p.owner);x.contracts++;if(p.status==="Ativo"&&!String(p.type||"").includes("Venda"))x.monthlyRevenue+=Number(p.monthly_value||0)}}return Array.from(map.values()).sort((a,b)=>b.wonValue-a.wonValue||b.won-a.won||a.seller.localeCompare(b.seller));},[rows]);
