 async function generateMonthlyCharges(){
  if(loading)return;
  const competence=todayKey.slice(0,7);
  const contracts=rows.filter(r=>r.module==="contracts"&&r.payload.status==="Ativo"&&!String(r.payload.type||"Locação").includes("Venda"));
  if(contracts.length===0){setNotice("Não há contratos ativos de locação para gerar cobranças.");return}
  const existing=new Set(rows.filter(r=>r.module==="finance").map(r=>String(r.payload.charge_key||((r.payload.contract_id&&r.payload.competence)?r.payload.contract_id+"|"+r.payload.competence:""))).filter(Boolean));
  const candidates=contracts.filter(contract=>!existing.has(contract.id+"|"+competence));
  let created=0,skipped=contracts.length-candidates.length,missing=0;
  const newRows:RecordItem[]=[];
  setLoading(true);
  for(const contract of candidates){
   const p=contract.payload||{},startDate=String(p.start_date||"").slice(0,10);
   if(!/^\d{4}-\d{2}-\d{2}$/.test(startDate)||startDate>todayKey){missing++;continue}
   const [year,month]=competence.split("-").map(Number),startDay=Number(startDate.slice(8,10));
   const lastDay=new Date(year,month,0).getDate(),dueDate=year+"-"+String(month).padStart(2,"0")+"-"+String(Math.min(startDay,lastDay)).padStart(2,"0");
   const status=dueDate<todayKey?"Pendente":"Previsto";
   const payload={description:"Locação mensal · "+String(p.number||contract.id)+" · "+competence,company:String(p.company||""),kind:"Receita",category:"Locação",amount:Number(p.monthly_value||0),due_date:dueDate,paid_date:"",status,contract_id:contract.id,contract_number:String(p.number||""),competence,charge_key:contract.id+"|"+competence,generated_by:"VEYRION monthly billing",notes:"Cobrança prevista gerada a partir do contrato ativo. Confirme valor, vencimento e pagamento manualmente."};
   if(demo){newRows.push({id:"demo-charge-"+contract.id+"-"+competence,module:"finance",payload,created_at:new Date().toISOString()});created++;continue}
   if(!supabase){setNotice("Conecte o banco de dados ou use a demonstração para gerar cobranças.");setLoading(false);return}
   const {data,error}=await supabase.from("workspace_records").insert({module:"finance",payload}).select().single();
   if(error){if(error.code==="23505"){skipped++;continue}setRows(prev=>[...newRows,...prev]);setNotice("Foram criadas "+created+" cobrança(s), mas houve falha no próximo registro: "+error.message+". Execute novamente para continuar sem duplicar as já gravadas.");setLoading(false);return}
   newRows.push(data as RecordItem);created++;
  }
  if(newRows.length)setRows(prev=>[...newRows,...prev]);
  setNotice(created+" cobrança(s) gerada(s) para "+competence+"; "+skipped+" já existiam; "+missing+" contrato(s) sem data de início válida ou com início futuro foram ignorados. Nenhuma cobrança foi marcada como paga.");
  setLoading(false);
 }

 function prepareCsv(file:File){
  if(file.size>5*1024*1024){setNotice("Arquivo acima de 5 MB. Divida a planilha e tente novamente.");return}
  if(!["companies","contacts"].includes(module)){setNotice("Importação disponível para empresas e contatos.");return}
  const reader=new FileReader();reader.onload=()=>{
   try{
    const parsed=parseCsv(String(reader.result||""));
    const aliases:Record<string,string>={name:"name",company:module==="companies"?"name":"company",razaosocial:"name",empresa:module==="companies"?"name":"company",nome:"name",nomecompleto:"name",cnpj:"cnpj",funcionarios:"employees",employees:"employees",setor:"sector",segmento:"sector",site:"website",website:"website",cidade:"city",cidadeuf:"city",telefone:"phone",phone:"phone",origem:"source",observacoes:"notes",email:"email",cargo:"role",departamento:"department",whatsapp:"whatsapp",poderdecisao:"decision_maker",notebooksestimados:"notebook_demand",notebooks:"notebook_demand",interesseemlocacao:"rental_interest",prioridadecomercial:"priority",prioridade:"priority",etapadaprospeccao:"prospect_stage",etapa:"prospect_stage",pessoadecontato:"contact_person",responsavelcontato:"contact_person",cargocontato:"contact_role",emailcontato:"contact_email",canalpreferido:"contact_channel",ultimocontato:"last_contact_at",proximaacaocomercial:"next_action",proximofollowup:"next_followup",followup:"next_followup"};
    const existing=new Set(rows.filter(x=>x.module===module).map(x=>String(x.payload[module==="companies"?"cnpj":"email"]||"").toLowerCase().replace(/[^a-z0-9]/g,"")).filter(Boolean));
    const seen=new Set<string>();
    const preview=parsed.records.map(values=>{
     const payload:Record<string,any>={};parsed.headers.forEach((h,i)=>{const key=aliases[h];if(key&&values[i])payload[key]=values[i]});
     if(module==="companies"&&payload.employees)payload.employees=Number(String(payload.employees).replace(/[^0-9]/g,""))||0;
     if(module==="companies"&&payload.notebook_demand)payload.notebook_demand=Number(String(payload.notebook_demand).replace(/[^0-9]/g,""))||0;
     const required=module==="companies"?["name","cnpj"]:["name","email"];
     let issue=required.some(k=>!String(payload[k]||"").trim())?"Campo obrigatório ausente": "";
     if(!issue&&module==="companies"&&String(payload.cnpj).replace(/\D/g,"").length!==14)issue="CNPJ deve conter 14 dígitos";
     if(!issue&&module==="contacts"&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(payload.email)))issue="E-mail inválido";
     const uniqueKey=String(payload[module==="companies"?"cnpj":"email"]||"").toLowerCase().replace(/[^a-z0-9]/g,"");
     if(!issue&&existing.has(uniqueKey))issue="Já existe no cadastro";
     else if(!issue&&seen.has(uniqueKey))issue="Duplicado no próprio arquivo";
     if(uniqueKey)seen.add(uniqueKey);
     return {payload,issue};
    });
    setCsvPreview(preview);setCsvName(file.name);setNotice("Prévia pronta: "+preview.filter(x=>!x.issue).length+" registros válidos; "+preview.filter(x=>x.issue).length+" ignorados.");
   }catch(e){setNotice(e instanceof Error?e.message:"Não foi possível ler o CSV.");setCsvPreview([])}
  };reader.onerror=()=>setNotice("Falha ao ler o arquivo.");reader.readAsText(file,"UTF-8");
 }
 async function confirmCsvImport(){
  const accepted=csvPreview.filter(x=>!x.issue);if(!accepted.length){setNotice("Não há linhas válidas para importar.");return}
  setImporting(true);
  if(demo){const now=new Date().toISOString();const added=accepted.map((x,i)=>({id:"csv-demo-"+Date.now()+"-"+i,module,payload:x.payload,created_at:now} as RecordItem));setRows(prev=>[...added,...prev]);setNotice(added.length+" registros adicionados somente à demonstração.");}
  else if(supabase){const {data,error}=await supabase.from("workspace_records").insert(accepted.map(x=>({module,payload:x.payload}))).select();if(error){setNotice("Importação não concluída: "+error.message);setImporting(false);return}setRows(prev=>[...((data||[]) as RecordItem[]),...prev]);setNotice((data||[]).length+" registros importados.");}
  else{setNotice("Configure o Supabase antes de importar.");setImporting(false);return}
  setCsvPreview([]);setCsvName("");if(csvInput.current)csvInput.current.value="";setImporting(false);
 }

 function exportCsv(){const list=module==="dashboard"?rows:visible;const keys=Array.from(new Set(list.flatMap(r=>Object.keys(r.payload))));const csv=[["Módulo",...keys].join(";"),...list.map(r=>[r.module,...keys.map(k=>String(r.payload[k]??"").replace(/;/g,","))].join(";"))].join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}));a.download="veyrion-export.csv";a.click();URL.revokeObjectURL(a.href)}
