 const display=(r:RecordItem)=>{const p=r.payload;return p.name||p.title||p.description||[p.brand,p.model].filter(Boolean).join(" ")||p.number||"Registro"};
 if(!user)return <main className="login panel"><div className="eyebrow">Tecnologia · Inteligência · Crescimento</div><h1>VEYRION OS</h1><p className="muted">Plataforma de gestão comercial, vendas e locação B2B.</p>{!configured&&<div className="notice">Backend ainda não configurado. Adicione as variáveis do Supabase na Vercel e execute o SQL de <b>supabase/schema.sql</b>.</div>}<label className="muted">E-mail corporativo</label><input className="field" type="email" placeholder="voce@empresa.com.br" value={email} onChange={e=>setEmail(e.target.value)}/><button className="btn" disabled={loading||!email} onClick={signIn}>{loading?"Enviando…":"Enviar link seguro de acesso"}</button><button className="btn secondary" style={{marginTop:10}} onClick={()=>{setUser({email:"demo@veyrion.local"});sample()}}>Visualizar demonstração</button>{notice&&<p className="footer-note">{notice}</p>}<p className="footer-note">Acesso por link mágico do Supabase Auth. Não há senha fictícia ou seleção livre de perfil.</p></main>;
 const title=NAV.find(n=>n[0]===module)?.[1]||"Visão geral";
